with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'ソクラテスの死', 'ジャック＝ルイ・ダヴィッド', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/The_Death_of_Socrates_MET_DP-13139-001.jpg/960px-The_Death_of_Socrates_MET_DP-13139-001.jpg', '1787年のサロンに出品された、新古典主義を代表する一枚です。死刑を宣告された古代ギリシャの哲学者ソクラテスが、毒杯に手を伸ばしながらも、もう一方の手を上に掲げて弟子たちに語り続ける場面が描かれています。嘆き悲しむ弟子たちと、落ち着いた師の姿の対比が見どころです。寝台の足もとに背を向けて座る老人はプラトンとされます。現在はニューヨークのメトロポリタン美術館が所蔵しています。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:The_Death_of_Socrates_MET_DP-13139-001.jpg'),
    (2, '八橋図屏風', '尾形光琳', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/%E5%85%AB%E6%A9%8B%E5%9B%B3%E5%B1%8F%E9%A2%A8_-Irises_at_Yatsuhashi_%28Eight_Bridges%29_MET_DT231.jpg/960px-%E5%85%AB%E6%A9%8B%E5%9B%B3%E5%B1%8F%E9%A2%A8_-Irises_at_Yatsuhashi_%28Eight_Bridges%29_MET_DT231.jpg', '『伊勢物語』の東下りで、在原業平らが三河国の八橋に咲くかきつばたを見て歌を詠む場面に取材した六曲一双の屏風です。人物は描かず、金地にかきつばたの群れと、ジグザグに渡る板橋だけで物語を思わせます。根津美術館の国宝「燕子花図屏風」より後の作とされ、橋を加えたことで画面に奥行きとリズムが生まれました。メトロポリタン美術館が所蔵しています。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:八橋図屏風_-Irises_at_Yatsuhashi_(Eight_Bridges)_MET_DT231.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「Art Collaboration Kyoto 2026」開幕', '国内ギャラリーが海外ギャラリーとブースを共有するアートフェアが、国立京都国際会館で6回目の開催。', '現代アートフェア「Art Collaboration Kyoto（ACK）2026」が11月7日、国立京都国際会館で開幕した。会期は9日まで。2021年に始まり6回目で、国内ギャラリーが海外ギャラリーを招いて1つのブースを共有する「ギャラリーコラボレーション」が特徴。今回は18の国と地域、24都市から63ギャラリーが参加した。運営面では、プログラムディレクターを務めてきた山下有佳子に代わり、7名のディレクターによる共同ディレクション体制「リーダーシップコミッティー」が発足し、従来の単一テーマの設定をやめた。ハウザー＆ワースとジェフリー・ダイチが初参加している。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/market/33303',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('SIDE COREが北杜市2会場で「Hokuto Road Side」', '清春芸術村とGASBON METABOLISMで、「道」と「移動」を手がかりにした新作を発表。', '東京を拠点に活動するアーティストコレクティブSIDE COREによる展覧会「Hokuto Road Side」が、山梨県北杜市の清春芸術村とGASBON METABOLISMの2会場で開催される。会期は2026年11月14日から2027年2月28日まで。「道」と「移動」を手がかりに、東京と山梨を結ぶ道路や物流、山間部の自然と人々の暮らしに目を向ける。清春芸術村では「路上の光」をテーマにした新作シリーズ「トワイライト・オブジェクツ」を、GASBON METABOLISMでは北杜市の山間部に点在する砂防ダムをテーマにした映像と立体の新作シリーズ「チェック・ザ・ダム」を発表する。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33281',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ヘルシンキ・ビエンナーレ2027、16組を追加発表', '片岡真実が共同キュレーターを務め、ユアサエボシやイケムラレイコらの参加が決まった。', 'フィンランドの首都ヘルシンキで2027年6月6日から9月19日まで開かれる「ヘルシンキ・ビエンナーレ2027」の参加作家16組が新たに発表された。2021年に始まった国際現代美術展の4回目で、テーマは「Unknowns（未知なるもの）」。森美術館館長の片岡真実と、HAM ヘルシンキ美術館館長のアルヤ・ミラーが共同でキュレーションを務める。11月5日に東京のフィンランド大使館で発表会が行われ、ユアサエボシ、イケムラレイコ、瀬戸桃子、トーベ・ヤンソンらの名前が挙がった。既に発表されている奈良美智を含め28組が決まっており、最終的には約45組が参加する予定。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/headline/33294',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('馬の市', 'The Horse Fair', 'ローザ・ボヌール', 'Rosa Bonheur',
        1853,
        (select slug from public.art_movements where slug = 'realism'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Rosa_Bonheur%2C_The_Horse_Fair%2C_1852%E2%80%9355.jpg/960px-Rosa_Bonheur%2C_The_Horse_Fair%2C_1852%E2%80%9355.jpg', 'パリの馬市を、幅5メートルを超える大画面に描いた作品です。1853年のサロンに出品されて評判を呼び、ボヌールの名を広く知らしめました。ボヌールは家畜の市場に通って写生を重ねるため、警察に許可を得てズボンをはいたことでも知られます。神話や歴史の場面ではなく、目の前の動物と人の働く姿を力強く描いた点に、写実主義の姿勢がよく表れています。たくましい馬の筋肉や、土ぼこりの立つ動きの表現が見どころです。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Rosa_Bonheur,_The_Horse_Fair,_1852–55.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('絵画の寓意としての自画像', 'Self-Portrait as the Allegory of Painting', 'アルテミジア・ジェンティレスキ', 'Artemisia Gentileschi',
        null,
        (select slug from public.art_movements where slug = 'baroque'),
        '英国王室コレクション', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Self-portrait_as_the_Allegory_of_Painting_%28La_Pittura%29_-_Artemisia_Gentileschi.jpg/960px-Self-portrait_as_the_Allegory_of_Painting_%28La_Pittura%29_-_Artemisia_Gentileschi.jpg', '画家自身を「絵画」の擬人像として描いた自画像です。体をひねってカンヴァスに向かう瞬間をとらえ、乱れた髪や仮面のついた金の鎖など、当時の寓意の手引き書に記された「絵画」の特徴を取り入れています。男性の画家が理想化された女性像で「絵画」を表すことが多かったなかで、女性画家である自分を、働く姿のまま「絵画」そのものとして示した点が独創的です。カラヴァッジョから受け継いだ強い明暗が、腕と顔を浮かび上がらせています。1630年代末、ロンドン滞在の頃の作とされます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Self-portrait_as_the_Allegory_of_Painting_(La_Pittura)_-_Artemisia_Gentileschi.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
