insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ローザ・ボヌール', 'Rosa Bonheur', 'ボヌール',
        1822, 1899, 'west', array['realism']::text[],
        '馬や牛などの動物を力強く描いた、19世紀フランスの写実主義の画家・彫刻家。', '1822年、フランスのボルドーに生まれました。画家だった父レーモン・ボヌールから絵の基礎を学び、早くから動物のデッサンに打ち込みました。

動物を正確に描くため、家畜の市場などに通って写生を重ねました。市場に通うために警察からズボンの着用許可を得ていたことでも知られます。サロンでは1845年に3等メダル、1848年に1等メダルを受け、1849年の『ニヴェルネー地方の耕作』、1853年のサロンに出した大作『馬の市』で名声を確かなものにしました。

1865年には、女性の芸術家として初めてレジオンドヌール勲章シュヴァリエを受けています。1859年に購入したフォンテーヌブロー近郊ビーの城をアトリエとし、多くの動物を飼いながら制作を続け、1899年に亡くなりました。その城は現在、ローザ・ボヌール美術館として公開されています。', 'https://ja.wikipedia.org/wiki/%E3%83%AD%E3%83%BC%E3%82%B6%E3%83%BB%E3%83%9C%E3%83%8C%E3%83%BC%E3%83%AB')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アルテミジア・ジェンティレスキ', 'Artemisia Gentileschi', 'アルテミジア',
        1593, null, 'west', array['baroque']::text[],
        'カラヴァッジョの影響を受けた劇的な明暗表現で知られる、17世紀イタリアのバロックの女性画家。', '1593年、ローマに生まれました。父は画家のオラツィオ・ジェンティレスキで、父のもとで絵を学び、カラヴァッジョの強い明暗表現を身につけました。

フィレンツェに移ってからは芸術院に女性として初めて迎えられ、その後ローマ、ヴェネツィア、ナポリへと拠点を移しながら制作しました。旧約聖書の女性ユディトなど、力強い女性を主人公にした場面を劇的な光と闇で描き、『ホロフェルネスの首を斬るユディト』はその代表作です。1638年頃にはロンドンに渡って父の仕事を手伝い、『絵画の寓意としての自画像』もこの頃の作とされます。

晩年はナポリで過ごし、1650年代に没したとされます。長く父の陰に隠れていましたが、1970年代以降、女性画家の先駆けとして再評価が進みました。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%AB%E3%83%86%E3%83%9F%E3%82%B8%E3%82%A2%E3%83%BB%E3%82%B8%E3%82%A7%E3%83%B3%E3%83%86%E3%82%A3%E3%83%AC%E3%82%B9%E3%82%AD')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('イリヤ・レーピン', 'Ilya Repin', 'レーピン',
        1844, 1930, 'west', array['realism']::text[],
        '民衆の姿や歴史の場面を迫真の描写で描いた、19世紀ロシア写実主義を代表する画家。', '1844年、ロシア帝国のチュグエフに生まれました。地元のイコン画家のもとで修業したのち、ペテルブルクの帝国美術アカデミーで学び、1873年から1876年にかけてイタリアとパリに留学しました。

ヴォルガ川で船を曳く労働者たちを描いた『ヴォルガの舟曳き』で注目を集め、1878年には、アカデミーの外で展覧会を各地に巡回させた「移動派」（巡廻美術展協会）に加わりました。民衆の行列を描いた『クルスク県の復活大祭の十字行』、流刑から戻った男と家族を描いた『思いがけなく』など、社会の現実と人の心の動きを鋭くとらえた作品を残しています。

歴史画『イワン雷帝と皇子イワン』『トルコのスルタンへ手紙を書くザポロージャ・コサック』も代表作です。晩年はフィンランド湾岸クオッカラの自宅「ペナトゥイ」で過ごし、1930年に亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%82%A4%E3%83%AA%E3%83%A4%E3%83%BB%E3%83%AC%E3%83%BC%E3%83%94%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
